import {useId} from 'react';
import './workspace.css';
export type Item={id:string;title:string};
export type ListState={items:readonly Item[]|null;pending:boolean;error:string|null};
export function ListWorkspace({state,onRefresh,onCreate,onOpen}:{state:ListState;onRefresh:()=>void;onCreate:()=>void;onOpen:(id:string)=>void}){
 const id=useId(); const {items,pending,error}=state;
 return <section className="list-workspace" aria-labelledby={id}><header><h1 id={id}>Projects</h1><button disabled={pending} onClick={onRefresh}>Refresh</button></header>
  <p role="status" aria-live="polite">{pending?(items===null?'Loading projects…':'Refreshing projects; showing saved results.'):items!==null?items.length+' projects':''}</p>
  {error&&<div className="list-error" role="alert"><strong>{items===null?'Could not load projects.':'Could not refresh projects.'}</strong><p>{error}</p>{items!==null&&<p>Your previous results remain available.</p>}<button onClick={onRefresh} disabled={pending}>Try again</button></div>}
  <div aria-busy={pending}>{items!==null&&(items.length===0?<div className="empty"><h2>No projects yet</h2><p>Create a project to start organizing your work.</p><button onClick={onCreate}>Create project</button></div>:<ul>{items.map(item=><li key={item.id}><button onClick={()=>onOpen(item.id)}>{item.title}</button></li>)}</ul>)}</div>
 </section>;
}
// Application reducer preserves stale results throughout request and failure transitions.
export type ListAction={type:'request'}|{type:'success';items:Item[]}|{type:'failure';message:string};
export function listReducer(state:ListState,action:ListAction):ListState{
 switch(action.type){case 'request':return {...state,pending:true,error:null};case 'success':return {items:action.items,pending:false,error:null};case 'failure':return {...state,pending:false,error:action.message};}
}
export const initialListState:ListState={items:null,pending:true,error:null};
